using System;using Ossastra.AnimationCore;
class AnimationTests{static int n;static void Check(bool v,string s){if(!v)throw new Exception(s);Console.WriteLine("PASS "+s);n++;}static void Main(){
var route=new AnimationResolvePolicy("a");var id=Guid.NewGuid();var move=new AnimationIntent("a",AnimationSemantic.Move,"movement",Guid.Empty,0);var atk=new AnimationIntent("a",AnimationSemantic.BasicAttack,"action",id,0);
Check(route.Resolve(new[]{move,atk},0).Value.Semantic==AnimationSemantic.BasicAttack,"attack outranks motion");Check(route.Resolve(new[]{atk,move},0).Value.ReplayId==id,"stable priority independent input order");Check(!route.Resolve(new[]{atk},1).HasValue,"expired generation rejected");Check(!route.Resolve(new[]{new AnimationIntent("b",AnimationSemantic.Death,"life",id,0)},0).HasValue,"foreign actor rejected");
var death=new AnimationIntent("a",AnimationSemantic.Death,"life",id,0);Check(route.Resolve(new[]{death,atk},0).Value.Semantic==AnimationSemantic.Death,"death dominates");var broken=new AnimationIntent("a",AnimationSemantic.PostureBroken,"posture",id,0);Check(route.Resolve(new[]{atk,broken},0).Value.Semantic==AnimationSemantic.PostureBroken,"stagger dominates action");
var state=new AnimationPlaybackIdentity();Check(state.ShouldCommit("atk1",atk),"first commit");Check(!state.ShouldCommit("atk1",atk),"same identity no replay");Check(state.ShouldCommit("atk1",new AnimationIntent("a",AnimationSemantic.BasicAttack,"action",Guid.NewGuid(),0)),"new action same clip replays");Check(state.ShouldCommit("idle",new AnimationIntent("a",AnimationSemantic.Idle,"movement",Guid.Empty,1)),"new generation returns idle");Console.WriteLine(n+" animation contracts passed");}}
